import{c as a,Q as t,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"环境准备","description":"","frontmatter":{},"headers":[{"level":1,"title":"环境准备","slug":"环境准备"}],"relativePath":"guide/入门教程/环境准备.md","filePath":"guide/入门教程/环境准备.md"}'),r={name:"guide/入门教程/环境准备.md"};function o(c,e,i,p,l,d){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="环境准备" tabindex="-1">环境准备 <a class="header-anchor" href="#环境准备" aria-label="Permalink to &quot;环境准备&quot;">​</a></h1><ul><li><p>进行Ascend C算子开发之前，需要安装<strong>驱动固件</strong>和<strong>CANN软件包</strong>，请参考<a href="https://www.hiascend.com/cann/download" target="_blank" rel="noreferrer">《CANN 快速安装》</a>完成环境准备。</p><pre><code>&gt; [!NOTE] 说明\n&gt; 安装CANN软件包后，使用CANN运行用户进行编译、运行时，需要以CANN运行用户登录环境，执行 `source ${INSTALL_DIR}/set_env.sh` 命令设置环境变量。`${INSTALL_DIR}` 请替换为CANN软件安装后的文件存储路径。以root用户安装为例，安装后文件默认存储路径为：/usr/local/Ascend/cann。\n</code></pre></li><li><p>安装CMake。通过CMake编译Ascend C算子时，要求安装3.16及以上版本的CMake，如果版本不符合要求，可以参考如下示例安装满足要求的版本。</p><p>示例：安装3.16.0版本的CMake（x86_64架构）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkdir -p cmake-3.16 &amp;&amp; wget -qO- &quot;https://cmake.org/files/v3.16/cmake-3.16.0-Linux-x86_64.tar.gz&quot; | tar --strip-components=1 -xz -C cmake-3.16</span></span>\n<span class="line"><span>export PATH=`pwd`/cmake-3.16/bin:$PATH</span></span></code></pre></div></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>对于Ascend C算子的开发，并非必须安装驱动固件。在非昇腾设备上，可以利用CPU仿真环境先行进行算子开发和测试，并在准备就绪后，利用昇腾设备进行加速计算。非昇腾设备的安装请参考 <a href="https://www.hiascend.com/document/redirect/CannCommunityInstSoftware" target="_blank" rel="noreferrer">《CANN安装指南》</a>中“附录B：常用操作 &gt; 在非昇腾设备上安装CANN”章节。</p></div>',3)])])}const u=a(r,[["render",o]]);export{m as __pageData,u as default};
